18	  name: 'DateTime',
19	  description: 'An ISO-8601 encoded UTC date string.',
20	  serialize(value) {
21	    // value sent to the client
22	    if (!(value instanceof Date)) throw new TypeError('DateTime can only serialize Date objects');
23	    return value.toISOString();
24	  },
25	  parseValue(value) {
26	    // value from the client (variables)
27	    const date = new Date(value);
28	    if (Number.isNaN(date.getTime())) throw new TypeError('Invalid DateTime value');
29	    return date;
30	  },
31	  parseLiteral(ast) {
32	    // value from the client (inline)
33	    if (ast.kind !== Kind.STRING) throw new TypeError('DateTime literal must be a string');
34	    const date = new Date(ast.value);
35	    if (Number.isNaN(date.getTime())) throw new TypeError('Invalid DateTime value');
