169	/**
170	 * GET /:version/prompts.csv
171	 * Downloads prompts as CSV
172	 */
173	async function downloadPromptsCSV(req, res, next) {
174	  const version = req.params.version || 'v1';
175	  const impl = selectVersionedImplementation(version);
176	
177	  try {
178	    const csvStream = await impl.exportPromptsAsCSV();
179	    // Attach headers for download
180	    res.setHeader('Content-Type', 'text/csv');
181	    res.setHeader(
182	      'Content-Disposition',
183	      `attachment; filename="canvaschord_prompts_${version}.csv"`
184	    );
185	    csvStream.pipe(res);
186	    logger.info('Prompt CSV streamed', { version });
187	  } catch (err) {
188	    logger.error('CSV export failed', { err, version });
189	    next(err);
190	  }
191	}
